.btn {
  font: 700 15px/1 'Rebel Sans', 'Pretendard', -apple-system, sans-serif;
  border-radius: 9999px;
  padding: 0 22px;
  height: 44px;
  display: inline-flex; align-items: center; gap: 6px;
